import { defineConfig } from 'orval'

// Generates the typed API client and TanStack Query hooks from the contract.
// Do not edit src/shared/api/generated by hand: change api/openapi.yaml and run `pnpm generate`.
export default defineConfig({
  nexo: {
    input: { target: '../api/openapi.yaml' },
    output: {
      mode: 'tags-split',
      target: 'src/shared/api/generated',
      schemas: 'src/shared/api/generated/model',
      client: 'react-query',
      httpClient: 'fetch',
      baseUrl: '/api/v1',
      clean: true,
      override: {
        mutator: { path: 'src/shared/api/http-client.ts', name: 'httpClient' },
        // Return the body directly; errors are thrown as ApiError by the mutator.
        fetch: { includeHttpResponseReturnType: false },
      },
    },
  },
})
